mapper.delete:
delete from CHB_BOT_AST_POS
where POS_DATE = #{batchTime,jdbcType=TIMESTAMP}
and DATASOURCE = '16'/*为避免误删除业务数据维护导入的数据，增加此条件*/

/*begin*/

  delete from CHB_BOT_AST_POS
  where PLAN_ASSET_ID = #{item.posId,jdbcType=VARCHAR} and POS_DATE = #{item.posDate,jdbcType=TIMESTAMP}
  and ASSET_CODE = #{item.assetCode,jdbcType=VARCHAR}

;/*end;*/

mapper.insert:
insert into CHB_BOT_AST_POS(POS_ID, ISSUE_PARTY_ID, POS_DATE, PLAN_ASSET_ID, ASSET_CODE, TOTAL_NUM, ISSUE_AMT, UNINVEST_CASH, POS_NUM, POS_AMT, ISFINAPLAN, ISCHL, WORKFLOW_ID, STATUS, ORG_CODE, DEPT_CODE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, DATASOURCE) select POS_ID, ISSUE_PARTY_ID, POS_DATE, PLAN_ASSET_ID, ASSET_CODE, TOTAL_NUM, ISSUE_AMT, UNINVEST_CASH, POS_NUM, POS_AMT, ISFINAPLAN, ISCHL, WORKFLOW_ID, STATUS, ORG_CODE, DEPT_CODE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, DATASOURCE from ( select TEMP.* from (
SELECT #{item.posId,jdbcType=CHAR} POS_ID, #{item.issuePartyId,jdbcType=VARCHAR} ISSUE_PARTY_ID, #{item.posDate,jdbcType=TIMESTAMP} POS_DATE, #{item.planAssetId,jdbcType=VARCHAR} PLAN_ASSET_ID, #{item.assetCode,jdbcType=VARCHAR} ASSET_CODE, #{item.totalNum,jdbcType=DECIMAL} TOTAL_NUM, #{item.issueAmt,jdbcType=DECIMAL} ISSUE_AMT, #{item.uninvestCash,jdbcType=DECIMAL} UNINVEST_CASH, #{item.posNum,jdbcType=DECIMAL} POS_NUM, #{item.posAmt,jdbcType=DECIMAL} POS_AMT, #{item.isfinaplan,jdbcType=CHAR} ISFINAPLAN, #{item.ischl,jdbcType=CHAR} ISCHL, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.status,jdbcType=VARCHAR} STATUS, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT , NOW() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.datasource,jdbcType=VARCHAR} DATASOURCE FROM DUAL
) TEMP where not exists (select 1 from CHB_BOT_AST_POS CII where CII.PLAN_ASSET_ID = TEMP.PLAN_ASSET_ID and CII.ASSET_CODE = TEMP.ASSET_CODE and CII.POS_DATE = TEMP.POS_DATE) ) de ;
UPDATE CHB_BOT_AST_POS as A, ( select POS_ID, ISSUE_PARTY_ID, TOTAL_NUM, ISSUE_AMT, UNINVEST_CASH, POS_NUM, POS_AMT, ISFINAPLAN, ISCHL, WORKFLOW_ID, STATUS, ORG_CODE, DEPT_CODE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, DATASOURCE from ( select TEMP.* from (
SELECT #{item.posId,jdbcType=CHAR} POS_ID, #{item.issuePartyId,jdbcType=VARCHAR} ISSUE_PARTY_ID, #{item.posDate,jdbcType=TIMESTAMP} POS_DATE, #{item.planAssetId,jdbcType=VARCHAR} PLAN_ASSET_ID, #{item.assetCode,jdbcType=VARCHAR} ASSET_CODE, #{item.totalNum,jdbcType=DECIMAL} TOTAL_NUM, #{item.issueAmt,jdbcType=DECIMAL} ISSUE_AMT, #{item.uninvestCash,jdbcType=DECIMAL} UNINVEST_CASH, #{item.posNum,jdbcType=DECIMAL} POS_NUM, #{item.posAmt,jdbcType=DECIMAL} POS_AMT, #{item.isfinaplan,jdbcType=CHAR} ISFINAPLAN, #{item.ischl,jdbcType=CHAR} ISCHL, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.status,jdbcType=VARCHAR} STATUS, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT , NOW() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.datasource,jdbcType=VARCHAR} DATASOURCE FROM DUAL
) TEMP ) de ) AS B set A.POS_ID = B.POS_ID, A.ISSUE_PARTY_ID = B.ISSUE_PARTY_ID, A.TOTAL_NUM = B.TOTAL_NUM, A.ISSUE_AMT = B.ISSUE_AMT, A.UNINVEST_CASH = B.UNINVEST_CASH, A.POS_NUM = B.POS_NUM, A.POS_AMT = B.POS_AMT, A.ISFINAPLAN = B.ISFINAPLAN, A.ISCHL = B.ISCHL, A.WORKFLOW_ID = B.WORKFLOW_ID, A.STATUS = B.STATUS, A.ORG_CODE = B.ORG_CODE, A.DEPT_CODE = B.DEPT_CODE, A.CREATE_USER = B.CREATE_USER, A.CREATE_DEPT = B.CREATE_DEPT, A.CREATE_TIME = B.CREATE_TIME, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME, A.DATASOURCE = B.DATASOURCE where A.PLAN_ASSET_ID = B.PLAN_ASSET_ID and A.ASSET_CODE = B.ASSET_CODE and A.POS_DATE = B.POS_DATE;

mapper.select:
SELECT SUB.VAL_DATE POS_DATE, SUB.PTL_ID PLAN_ASSET_ID, SUB.FINPROD_ID ASSET_CODE, IFNULL(SUM(SUB.SECURITY_QUANTITY), 0) * (CASE WHEN DC.SUB_CLASS = 'ZQ' THEN IFNULL(HB.REPAY_NET, 100) ELSE 1 END) POS_NUM, IFNULL(SUM(SUB.SMV), 0) POS_AMT, IFNULL(SUM(CASE WHEN SUB.SUB_CODE LIKE '1204%' OR SUB.SUB_CODE LIKE '1203%' THEN SUB.SMV ELSE 0 END),0) INT_AMT,/** 利息**/ MAX(IFNULL(SUB.CREATE_TIME, SUB.UPDATE_TIME)) UPDATE_TIME FROM RSK_VALTBL_ASSET_SUB SUB /** 估值表导入后的资产数据**/
/** 估值表对应的资产科目类型，债券的数量需要乘以面值**/ INNER JOIN RSK_VALTBL_PRT_BOTASSET_MAP DC ON SUB.PTL_ID = DC.PTL_ID AND SUB.SUB_CODE = DC.SUB_CODE AND SUB.FINPROD_ID = DC.FINPROD_ID
/** 取债券还本计划的最近日期**/ LEFT JOIN ( SELECT T.SEC_ID, REPAY_NET FROM ( SELECT SEC_ID, REPAY_NET, RANK() OVER (PARTITION BY SEC_ID ORDER BY REPAY_DT DESC) MY_RANK FROM CHB_SEC_REPAY_INFO WHERE REPAY_DT <= #{batchTime,jdbcType=DATE} GROUP BY SEC_ID, REPAY_NET ) T WHERE MY_RANK = 1 ) HB ON HB.SEC_ID = SUB.FINPROD_ID WHERE 1 = 1 AND SUB.VAL_DATE = #{batchTime,jdbcType=DATE} AND SUB.FINPROD_ID IS NOT NULL AND DC.SUB_CLASS NOT IN ('ZHG', 'NHG') /** 过滤回购资产通过三级科目来计算**/
and left(DC.SUB_CODE,8) NOT IN ('11030102','11031102','11032102')
GROUP BY SUB.VAL_DATE, SUB.PTL_ID, SUB.VAL_DATE, SUB.FINPROD_ID
